**Étape 2 : règles à ajouter à la fin de** `mesStyles.css`

```css mesStyles.css
/* Règles demandées */
h1, nav {
  text-align: center;
}
aside img {
  filter: invert(100%);
}
ul {
  list-style-type: square;
  font-style: italic;
}
input[type="text"], input[type="email"], input[type="password"], input[type="number"] {
  color: #009933;
  background-color: #FFFFD8;
  padding: 4px;
}
footer {
  clear: both;
}
```

Le `target="zone"` des liens est égal au `name` de l'iframe. `aside img` n'inverse que l'image de la colonne de droite : un `img` seul toucherait aussi `parcelles.jpeg` dans l'iframe, et l'image, devenue un élément filtré, passerait **au-dessus** des numéros de parcelles. `clear: both` pousse le pied de page sous `section` et `aside`.

À écrire dans `mesControles.js` :

```js mesControles.js
/* une lettre (accentuée ou non) a une majuscule différente de sa minuscule */
function estLettre(c)
{
  return c.toLowerCase() != c.toUpperCase()
}

/* le même contrôle du mot de passe est utilisé dans deux pages */
function mdpValide(mdp)
{
  if (mdp.length != 6)
    return false
  if (mdp.indexOf(" ") != -1)
    return false
  return true
}

function inscription()
{
  let nom = document.getElementById("nom").value
  let ok = nom.length > 0 && nom.length <= 50 && nom.indexOf(" ") != -1
  if (ok)
  {
    ok = estLettre(nom.charAt(0)) && estLettre(nom.charAt(nom.length - 1))
    for (let i = 0; i < nom.length; i++)
      if (!estLettre(nom.charAt(i)) && nom.charAt(i) != " ")
        ok = false
  }
  if (!ok)
  {
    alert("Nom invalide : lettres et espaces, au moins un espace, 50 caractères au plus")
    return false
  }

  let email = document.getElementById("email").value
  if (email.length > 50 || !estLettre(email.charAt(0)) || email.slice(-3) != ".tn")
  {
    alert("Adresse email invalide : elle commence par une lettre et se termine par .tn")
    return false
  }

  let annee = Number(document.getElementById("dateNais").value.slice(0, 4))
  if (annee < 1950 || annee > 2006)
  {
    alert("L'année de naissance doit être comprise entre 1950 et 2006")
    return false
  }

  let radios = document.getElementsByName("genre")
  if (!radios[0].checked && !radios[1].checked)
  {
    alert("Choisissez un genre")
    return false
  }

  let mdp = document.getElementById("mdp").value
  if (!mdpValide(mdp))
  {
    alert("Le mot de passe contient 6 caractères sans espace")
    return false
  }
  if (document.getElementById("mdp2").value != mdp)
  {
    alert("Les deux mots de passe sont différents")
    return false
  }
  return true
}
```

À chaque `return false`, la fonction s'arrête et le formulaire n'est pas envoyé. La fonction `mdpValide` sert aussi dans `affectation()` (question 3-c). Si la page contient un nom avec un accent, `estLettre` l'accepte aussi.

